mapper.select:
select ps.*
    from product_sku ps
    inner join product p on ps.product_id = p.id
where p.status = 1 and p.is_deleted = 0 and ps.is_deleted = 0

    and ps.sku_name like concat('%',#{dto.skuName},'%')


    and p.brand_id = #{dto.brandId}


    and p.category1_id = #{dto.category1Id}


    and p.category2_id = #{dto.category2Id}


    and p.category3_id = #{dto.category3Id}


    order by sku.sale_num desc


    order by ps.sale_price


    order by ps.sale_price desc
